void _fastcall win_PrintTextInRect(int first, char far *text, struct Rect far *rect)
{
    int c;
    int start;
    int pixw;
    int brk;
    int line;
    int done;
    char far *p;
    int y;
    int w;
    int lh;
    int nlines;
    int len;
    char buf[150];
    int i;

    w = rect->right - rect->left;
    y = rect->top;
    lh = f_24AB_030B();
    nlines = (rect->bottom - rect->top) / lh;
    line = 0;
    while (*text) {
        if (first + nlines <= line)
            break;
        p = text;
        done = start = i = brk = pixw = 0;
        while (pixw < w && !done) {
            c = *p++;
            pixw += f_24AB_0367(c);
            if (pixw < w) {
                switch (c) {
                case 0:
                case 10:
                case 13:
                    done = 1;
                case ' ':
                case '(':
                case '[':
                case '{':
                    brk = i - 1;
                    break;
                case '!':
                case ')':
                case ',':
                case '-':
                case '.':
                case '?':
                case ']':
                case '}':
                    brk = i;
                    break;
                }
            }
            i++;
        }
        if (brk == start)
            brk = i - 1;
        if (first <= line) {
            len = brk + 1;
            _fstrncpy(buf, text, len);
            buf[len] = 0;
            f_24AB_038D(rect->left, y, buf);
        }
        text += len;
        while (*text == ' ')
            text++;
        if (*text == 10 || *text == 13)
            text++;
        y += lh;
        line++;
    }
}

